        poll.votes[i] += 1;
        poll.mine = i;
      }
      rerender(i);
    });
    return b;
  }));

  const SCENES = {
    rank: {
      channel: 'general',
      caption: 'nova checks their rank card, then levels up a few messages later. The card is drawn by the bot.',
      messages: () => [
        message('nova', 'Today at 21:40', { text: 'ok how close am I to level 13' }),
