async function api(path, { method = 'GET', body } = {}) {
  const headers = { Accept: 'application/json' };
  const init = { method, credentials: 'same-origin', headers };
  if (method === 'GET') {
    init.cache = 'no-store';
  } else {
    headers['Content-Type'] = 'application/json';
    headers['X-Dashboard'] = '1';
